import React, { useEffect, useState } from "react";
import { useSearchParams } from "react-router-dom";
import "./BuyHouseList.css";

// Safer INR formatter: never returns "—"
function formatCurrencyINR(value) {
  const n = Number(value);
  if (!isFinite(n) || n <= 0) return "₹0.00";
  if (n >= 1e7) return `₹${(n / 1e7).toFixed(2)} Cr`;
  if (n >= 1e5) return `₹${(n / 1e5).toFixed(2)} L`;
  return `₹${n.toLocaleString("en-IN", { maximumFractionDigits: 0 })}`;
}

export default function BuyHouseList() {
  const [searchParams] = useSearchParams();
  const cityFilter = searchParams.get("city");

  const [houses, setHouses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState("");
  const [revealed, setRevealed] = useState({});
  const [predicted, setPredicted] = useState({});
  const [predicting, setPredicting] = useState({});

  // Lightbox state
  const [lightboxSrc, setLightboxSrc] = useState(null);
  const openLightbox = (src) => setLightboxSrc(src);
  const closeLightbox = () => setLightboxSrc(null);

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      setErr("");
      try {
        const url = `${process.env.REACT_APP_BACKEND_URL}/buy/houses`;
        const res = await fetch(url);
        if (!res.ok) throw new Error("Failed to load");
        const data = await res.json();

        const houseArray = Array.isArray(data) ? data : [];

        // Client-side filtering with flexible matching
        let filteredHouses = houseArray;
        if (cityFilter && cityFilter.trim()) {
          const searchCity = cityFilter.trim().toLowerCase();

          // Normalize function - removes spaces, dashes, and special chars
          const normalize = (text) =>
            String(text || "")
              .toLowerCase()
              .replace(/\s+/g, "")
              .replace(/[-_]/g, "")
              .replace(/[^a-z0-9]/gi, "");

          const normalizedSearch = normalize(searchCity);

          filteredHouses = houseArray.filter((house) => {
            const houseCity = String(house.city || "").toLowerCase();
            const houseLocation = String(house.location || "").toLowerCase();

            // Try direct includes
            if (
              houseCity.includes(searchCity) ||
              houseLocation.includes(searchCity)
            ) {
              return true;
            }

            // Try normalized includes
            const normalizedCity = normalize(house.city);
            const normalizedLocation = normalize(house.location);

            return (
              normalizedCity.includes(normalizedSearch) ||
              normalizedLocation.includes(normalizedSearch)
            );
          });
        }

        setHouses(filteredHouses);
      } catch (e) {
        console.error("Fetch error:", e);
        setErr("Unable to fetch listings. Please try again.");
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [cityFilter]);

  // Close modal on Esc
  useEffect(() => {
    const onKey = (e) => {
      if (e.key === "Escape") closeLightbox();
    };
    if (lightboxSrc) window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [lightboxSrc]);

  const doPredict = async (h) => {
    const payload = {
      Area_sqft: h.area_sqft || 0,
      Property_Type: h.property_type || "",
      Bedrooms: h.bedrooms || 0,
      Bathrooms: h.bathrooms || 0,
      Year_Built: h.year_built || 0,
      Condition: h.condition || "",
      hospitalApplicable: "notApplicable",
      hospitalDistance: 0,
      schoolApplicable: "notApplicable",
      schoolDistance: 0,
      railwayApplicable: "notApplicable",
      railwayDistance: 0,
      busApplicable: "notApplicable",
      busDistance: 0,
      latitude: h.latitude || 0,
      longitude: h.longitude || 0,
    };

    setPredicting((p) => ({ ...p, [h.id]: true }));
    try {
      const res = await fetch(
        `${process.env.REACT_APP_BACKEND_URL}/predict/house`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        }
      );
      if (!res.ok) throw new Error("Predict failed");
      const data = await res.json();
      setPredicted((p) => ({ ...p, [h.id]: Number(data.price) }));
    } catch (e) {
      setPredicted((p) => ({ ...p, [h.id]: null }));
      alert("Prediction failed. Please try again.");
    } finally {
      setPredicting((p) => ({ ...p, [h.id]: false }));
    }
  };

  if (loading) return <div className="buy-loading">Loading listings...</div>;
  if (err) return <div className="buy-error">{err}</div>;

  return (
    <div className="buy-root">
      {/* Filter Header */}
      {cityFilter && (
        <div className="filter-header">
          <h2>
            Houses in <span className="city-name">{cityFilter}</span>
          </h2>
          <a href="/buy-house" className="clear-filter">
            ✕ Clear Filter
          </a>
        </div>
      )}

      {!houses.length ? (
        <div className="buy-empty">
          {cityFilter
            ? `No houses found in "${cityFilter}". Try a different city.`
            : "No houses found."}
        </div>
      ) : (
        houses.map((h) => {
          const isRevealed = revealed[h.id];
          const pred = predicted[h.id];

          // Normalize displayed numerics (never show "—")
          const actualPriceNum =
            h.actualPrice != null ? Number(h.actualPrice) : 0;
          const areaNum = Number(h.area_sqft || 0);
          const bedsNum = Number.isFinite(Number(h.bedrooms))
            ? Number(h.bedrooms)
            : 0;
          const bathsNum = Number.isFinite(Number(h.bathrooms))
            ? Number(h.bathrooms)
            : 0;

          const showDeal =
            typeof pred === "number" &&
            Number.isFinite(actualPriceNum) &&
            actualPriceNum > 0 &&
            pred < actualPriceNum;

          return (
            <div className="buy-card" key={h.id}>
              <div className="buy-card-left">
                <div className="buy-thumb">
                  {h.image ? (
                    <button
                      type="button"
                      className="thumb-click"
                      onClick={() =>
                        openLightbox(
                          `${process.env.REACT_APP_BACKEND_URL}${h.image}`
                        )
                      }
                      aria-label="View full image"
                    >
                      <img
                        src={`${process.env.REACT_APP_BACKEND_URL}${h.image}`}
                        alt=""
                      />
                    </button>
                  ) : (
                    <div className="no-img">No Image</div>
                  )}
                  <span className="badge">Resale</span>
                </div>
              </div>

              <div className="buy-card-mid">
                <div className="buy-title">
                  {h.property_type || "Property"} in{" "}
                  {h.city || h.location || ""}
                </div>

                <div className="buy-meta">
                  <div className="price">
                    {formatCurrencyINR(actualPriceNum)}
                  </div>
                  <div className="meta-item">
                    {areaNum.toLocaleString()} sq.ft
                  </div>
                  <div className="meta-item">{bedsNum} Beds</div>
                  <div className="meta-item">{bathsNum} Baths</div>
                </div>

                {pred != null && (
                  <div
                    className={`predict-row ${
                      showDeal ? "deal-ok" : "deal-warn"
                    }`}
                  >
                    <span>Model price: {formatCurrencyINR(pred)}</span>
                    {showDeal ? (
                      <span className="deal good">Good deal</span>
                    ) : (
                      <span className="deal warn">Above model</span>
                    )}
                  </div>
                )}

                {(h.location || h.city) && (
                  <div className="location-row">
                    <span className="pin">📍</span>
                    <span className="loc-text">{h.location || h.city}</span>
                  </div>
                )}
              </div>

              <div className="buy-card-right">
                <div className="btn-row">
                  <button
                    className="btn contact"
                    onClick={() =>
                      setRevealed((r) => ({ ...r, [h.id]: !isRevealed }))
                    }
                  >
                    {isRevealed ? h.contact || "NA" : "Contact"}
                  </button>

                  <button
                    className="btn predict"
                    disabled={predicting[h.id]}
                    onClick={() => doPredict(h)}
                  >
                    {predicting[h.id] ? "Predicting..." : "Predict"}
                  </button>
                </div>
              </div>
            </div>
          );
        })
      )}

      {/* Lightbox modal */}
      {lightboxSrc && (
        <div
          className="lb-overlay"
          onClick={closeLightbox}
          role="dialog"
          aria-modal="true"
        >
          <div className="lb-content" onClick={(e) => e.stopPropagation()}>
            <button className="lb-close" onClick={closeLightbox} aria-label="Close">
              ×
            </button>
            <img src={lightboxSrc} alt="" />
          </div>
        </div>
      )}
    </div>
  );
}
